package autonewsroller.video;

import java.nio.file.*;import java.util.*;
public final class VideoEncoderProbe {private final String ffmpeg;public VideoEncoderProbe(String ffmpeg){this.ffmpeg=ffmpeg;}public String resolve(String requested)throws Exception{String r=normalize(requested);if(r.equals("x264"))return "x264";Probe p=probeNvenc();if(p.ok)return "nvenc";if(r.equals("nvenc"))throw new IllegalStateException("NVENC explicitly requested but unavailable: "+p.reason);System.out.println("NVENC unavailable, using x264: "+p.reason);return "x264";}public static String normalize(String x){x=x==null?"auto":x.trim().toLowerCase(Locale.ROOT);return switch(x){case "","auto"->"auto";case "nvenc","nvidia","gpu"->"nvenc";case "x264","cpu","libx264"->"x264";default->throw new IllegalArgumentException("encoder must be auto, nvenc, or x264");};}
    private Probe probeNvenc(){Path out=null;try{String enc=FfmpegRunner.run(List.of(ffmpeg,"-hide_banner","-encoders"),20);if(!enc.toLowerCase().contains("h264_nvenc"))return new Probe(false,"FFmpeg does not list h264_nvenc");out=Files.createTempFile("autonews-nvenc-",".mp4");List<String>c=new ArrayList<>(List.of(ffmpeg,"-y","-hide_banner","-loglevel","error","-f","lavfi","-i","color=c=black:s=256x256:r=30:d=0.5","-frames:v","1","-an","-c:v","h264_nvenc","-preset","p4","-pix_fmt","yuv420p",out.toString()));FfmpegRunner.run(c,30);return new Probe(Files.size(out)>0,"available");}catch(Exception e){return new Probe(false,e.getMessage());}finally{if(out!=null)try{Files.deleteIfExists(out);}catch(Exception ignored){}}}
    private record Probe(boolean ok,String reason){}
}
